package config
import("errors";"fmt";"os";"strconv";"strings";"time")
type Config struct{AppEnv string;DatabaseURL string;APIDatabaseURL string;WorkerDatabaseURL string;APIAddr string;WorkerMetricsAddr string;APIToken string;APIKeys string;APIRateLimitRPS float64;APIRateLimitBurst int;WorkerID string;WorkerConcurrency int;PollInterval time.Duration;LeaseDuration time.Duration}
func Load()(Config,error){c:=Config{AppEnv:strings.ToLower(strings.TrimSpace(env("APP_ENV","development"))),DatabaseURL:os.Getenv("DATABASE_URL"),APIDatabaseURL:os.Getenv("API_DATABASE_URL"),WorkerDatabaseURL:os.Getenv("WORKER_DATABASE_URL"),APIAddr:env("API_ADDR",":8080"),WorkerMetricsAddr:env("WORKER_METRICS_ADDR",":9090"),APIToken:strings.TrimSpace(os.Getenv("API_TOKEN")),APIKeys:strings.TrimSpace(os.Getenv("API_KEYS")),WorkerID:env("WORKER_ID","worker-local")};if c.AppEnv!="development"&&c.AppEnv!="test"&&c.AppEnv!="production"{return Config{},errors.New("APP_ENV must be development, test, or production")};if c.DatabaseURL==""&&(c.APIDatabaseURL==""||c.WorkerDatabaseURL==""){return Config{},errors.New("DATABASE_URL or both API_DATABASE_URL and WORKER_DATABASE_URL are required")};if c.APIDatabaseURL==""{c.APIDatabaseURL=c.DatabaseURL};if c.WorkerDatabaseURL==""{c.WorkerDatabaseURL=c.DatabaseURL};var err error;c.PollInterval,err=duration("POLL_INTERVAL",time.Second);if err!=nil{return Config{},err};c.LeaseDuration,err=duration("LEASE_DURATION",30*time.Second);if err!=nil{return Config{},err};c.WorkerConcurrency,err=intValue("WORKER_CONCURRENCY",4);if err!=nil{return Config{},err};c.APIRateLimitRPS,err=floatValue("API_RATE_LIMIT_RPS",10);if err!=nil{return Config{},err};c.APIRateLimitBurst,err=intValue("API_RATE_LIMIT_BURST",20);if err!=nil{return Config{},err};if c.PollInterval<=0{return Config{},errors.New("POLL_INTERVAL must be positive")};if c.LeaseDuration<3*c.PollInterval{return Config{},errors.New("LEASE_DURATION must be at least three times POLL_INTERVAL")};if c.WorkerConcurrency<1||c.WorkerConcurrency>256{return Config{},errors.New("WORKER_CONCURRENCY must be between 1 and 256")};if c.APIRateLimitRPS<=0||c.APIRateLimitBurst<1{return Config{},errors.New("API rate limit values must be positive")};if c.WorkerID==""{return Config{},errors.New("WORKER_ID must not be empty")};if c.AppEnv=="production"{if len(c.APIToken)<32&&c.APIKeys==""{return Config{},errors.New("production requires API_TOKEN or API_KEYS with strong credentials")};if c.DatabaseURL!=""{return Config{},errors.New("production must configure separate API_DATABASE_URL and WORKER_DATABASE_URL credentials")}};if c.APIKeys!=""{seen:=make(map[string]struct{});for _,entry:=range strings.Split(c.APIKeys,","){parts:=strings.SplitN(strings.TrimSpace(entry),"=",2);if len(parts)!=2||strings.TrimSpace(parts[0])==""||parts[0]!=strings.TrimSpace(parts[0])||parts[1]!=strings.TrimSpace(parts[1])||len(parts[1])<32{return Config{},errors.New("API_KEYS entries must be client_id=token with tokens of at least 32 characters")};id:=strings.TrimSpace(parts[0]);if _,ok:=seen[id];ok{return Config{},errors.New("API_KEYS contains duplicate client IDs")};seen[id]=struct{}{}}};return c,nil}
func env(k,fallback string)string{if v:=os.Getenv(k);v!=""{return v};return fallback}
func duration(k string,fallback time.Duration)(time.Duration,error){v:=os.Getenv(k);if v==""{return fallback,nil};d,err:=time.ParseDuration(v);if err!=nil{return 0,fmt.Errorf("%s: %w",k,err)};return d,nil}
func intValue(k string,fallback int)(int,error){v:=os.Getenv(k);if v==""{return fallback,nil};n,err:=strconv.Atoi(v);if err!=nil{return 0,fmt.Errorf("%s: %w",k,err)};return n,nil}
func floatValue(k string,fallback float64)(float64,error){v:=os.Getenv(k);if v==""{return fallback,nil};n,err:=strconv.ParseFloat(v,64);if err!=nil{return 0,fmt.Errorf("%s: %w",k,err)};return n,nil}
